const identity = {
  schema: 'packet/v1',
  entry: 'index.html',
  report: { schema: report.schema, id: report.id, sourceSha256 },
  files: inventory, evidence: evidenceRelations, build: { tool: TOOL.name, version: TOOL.version },
};
const contentId = `sha256-${sha256Hex(canonicalBytes(identity))}`; // canonical JSON: sorted keys, no whitespace, RFC 8785 number form
const manifest = { ...identity, contentId };
/* Receipts, timestamps, and destination paths are written elsewhere and never enter `identity`. */

